using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgeCatalogOrderTests{[Fact]public void Valid_order_keeps_values(){var o=new AstronomyKnowledgeCatalogOrder(AstronomyKnowledgeCatalogSortField.Code,AstronomyKnowledgeQuerySortDirection.Descending,3);Assert.Equal(AstronomyKnowledgeCatalogSortField.Code,o.Field);Assert.Equal(AstronomyKnowledgeQuerySortDirection.Descending,o.Direction);Assert.Equal(3,o.Priority);}[Fact]public void Invalid_values_rejected(){Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeCatalogOrder((AstronomyKnowledgeCatalogSortField)99,AstronomyKnowledgeQuerySortDirection.Ascending));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeCatalogOrder(AstronomyKnowledgeCatalogSortField.Code,(AstronomyKnowledgeQuerySortDirection)99));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgeCatalogOrder(AstronomyKnowledgeCatalogSortField.Code,AstronomyKnowledgeQuerySortDirection.Ascending,-1));}[Fact]public void Query_normalizes_order_and_validator_detects_duplicates(){var q=new AstronomyKnowledgeCatalogQuery(ordering:[new(AstronomyKnowledgeCatalogSortField.Code,AstronomyKnowledgeQuerySortDirection.Ascending,1),new(AstronomyKnowledgeCatalogSortField.Code,AstronomyKnowledgeQuerySortDirection.Descending,1)]);Assert.Equal(1,q.Ordering[0].Priority);var issue=KnowledgeQueryFixture.Validator().Validate(q).Issues;Assert.Equal(AstronomyKnowledgeQueryValidationCode.DuplicateOrderField,issue[0].Code);Assert.Equal(AstronomyKnowledgeQueryValidationCode.DuplicateOrderPriority,issue[1].Code);}}
